/** Builds a 24dp icon from SVG path data; [top] handles Material Symbols' "0 -960 960 960" viewBox. */
private fun icon(name: String, viewport: Float, top: Float, pathData: String): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, viewport, viewport)
        .addGroup(translationY = -top)
        .addPath(pathData = addPathNodes(pathData), fill = SolidColor(Color.Black))
        .clearGroup()
        .build()
